<?php require __DIR__.'/../header.php';require __DIR__.'/../navbar.php';?><main class="container-fluid py-4 px-lg-4"><div class="d-flex justify-content-between align-items-center mb-3"><div><h2 class="mb-0">Vendedores</h2><span class="text-secondary">Los vendedores se crean desde Registrarse.</span></div><a class="btn btn-primary" href="index.php?c=vendedor&a=asignar">+ Asignar a campaña</a></div><div class="row g-3"><div class="col-xl-5"><div class="card"><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>Vendedor</th><th>Campañas</th></tr></thead><tbody><?php if(!$vendedores):?><tr><td colspan="2" class="vacio">No hay vendedores registrados.</td></tr><?php else:foreach($vendedores as $v):?><tr><td><strong><?=e($v['nombre'])?></strong><small class="d-block text-secondary"><?=e($v['email'])?></small></td><td><?=e($v['campanias'])?></td></tr><?php endforeach;endif;?></tbody></table></div></div></div><div class="col-xl-7"><div class="card"><div class="card-header bg-white"><h5 class="mb-0">Asignaciones</h5></div><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>Vendedor</th><th>Campaña</th><th>Estado</th><th>Cambiar</th></tr></thead><tbody><?php if(!$asignaciones):?><tr><td colspan="4" class="vacio">Todavía no hay asignaciones.</td></tr><?php else:foreach($asignaciones as $a):?><tr><td><?=e($a['vendedor'])?></td><td><?=e($a['campania'])?></td><td><?=e($a['estado'])?></td><td><form method="post" action="index.php?c=vendedor&a=estado" class="d-flex gap-2"><input type="hidden" name="id" value="<?=$a['id']?>"><select class="form-select form-select-sm" name="estado"><option value="ACTIVO">Activo</option><option value="INACTIVO">Inactivo</option></select><button class="btn btn-sm btn-outline-primary">Guardar</button></form></td></tr><?php endforeach;endif;?></tbody></table></div></div></div></div></main><?php require __DIR__.'/../footer.php';?>
